def minSubArrayLen_prefix(target, nums):
    from bisect import bisect_left
    n = len(nums)
    pre = [0] * (n + 1)
    for i in range(n):
        pre[i + 1] = pre[i] + nums[i]   # 前缀和，元素全为正 ⇒ pre 单调递增
    ans = n + 1
    for i in range(n):
        # 找最小 j > i 使 pre[j] - pre[i] >= target，即 pre[j] >= pre[i] + target
        j = bisect_left(pre, pre[i] + target, i + 1)
        if j <= n:
            ans = min(ans, j - i)
    return ans if ans <= n else 0

