class Solution {
public:
    int minSubArrayLen(int target, vector<int>& nums) {
        int n = (int)nums.size();
        int ans = n + 1;        // 哨兵：尚未找到满足条件的窗口
        long long window = 0;   // 当前窗口 [l, r] 的元素和（long long 防累加溢出）
        int l = 0;
        for (int r = 0; r < n; ++r) {
            window += nums[r];   // 右边界扩张，纳入新元素
            // 满足条件就尽量收缩左边界，寻找以 r 结尾的最短合法窗口
            while (window >= target) {
                ans = min(ans, r - l + 1);
                window -= nums[l];   // 移出左端元素
                ++l;
            }
        }
        // 全数组之和都达不到 target 时，哨兵未被触碰，返回 0
        return ans <= n ? ans : 0;
    }
};

